def diagram(name,kind):
    im=Image.new('RGB',(1500,640),'white'); d=ImageDraw.Draw(im)
    f=ImageFont.truetype(FONT,30); b=ImageFont.truetype(BOLD,34)
    def box(x,y,w,h,title,sub=''):
        d.rounded_rectangle((x,y,x+w,y+h),12,fill='#f1f3f5',outline='#333333',width=3)
        d.text((x+w/2,y+28),title,font=b,anchor='mt',fill='black')
        if sub: d.text((x+w/2,y+82),sub,font=f,anchor='mt',fill='#333333')
    def arrow(x1,y1,x2,y2):
        d.line((x1,y1,x2,y2),fill='#555555',width=5)
        import math
        a=math.atan2(y2-y1,x2-x1)
        pts=[(x2,y2),(x2-20*math.cos(a-.5),y2-20*math.sin(a-.5)),(x2-20*math.cos(a+.5),y2-20*math.sin(a+.5))]
        d.polygon(pts,fill='#555555')
    if kind=='architecture':
        box(20,240,270,130,'microSD / SSD','OS + files'); box(520,240,360,130,'BCM2712','CPU + GPU'); box(520,30,360,130,'RAM','working memory');box(1130,240,340,130,'HDMI','screen + sound');box(520,470,360,130,'RP1','I/O controller');box(1120,470,350,130,'USB / GPIO','peripherals')
        arrow(290,305,520,305);arrow(700,240,700,160);arrow(880,305,1130,305);arrow(700,370,700,470);arrow(880,535,1120,535)
    elif kind=='power':
        box(20,100,300,130,'USB-C supply','5.1 V / 5 A');box(500,100,350,130,'DA9091 PMIC','power management');box(1080,100,390,130,'Board circuits','CPU / RAM / I/O');arrow(320,165,500,165);arrow(850,165,1080,165)
        box(20,400,300,130,'RTC battery','BAT connector');box(500,400,350,130,'RTC','timekeeping');arrow(320,465,500,465)
        d.text((1050,440),'RTC battery does not',font=f,fill='black');d.text((1050,485),'power the computer.',font=f,fill='black')
    elif kind=='led':
        box(20,180,300,150,'GPIO17','physical pin 11');box(540,180,320,150,'Resistor','330 ohm');box(1060,180,330,150,'Red LED','anode (+)');arrow(320,255,540,255);arrow(860,255,1060,255)
        d.line((1225,330,1225,470,170,470),fill='#555',width=5);arrow(170,470,170,540)
        d.text((170,555),'GND - physical pin 6',font=b,fill='black',anchor='mt');d.text((950,400),'cathode (-)',font=f,fill='black')
    elif kind=='buses':
        box(20,50,300,130,'I2C','shared bus');box(560,50,260,130,'Sensor A','address 0x40');box(1100,50,320,130,'Sensor B','address 0x76')
        d.line((170,180,170,215,1260,215),fill='#555',width=5);arrow(690,215,690,180);arrow(1260,215,1260,180)
        box(20,260,300,130,'SPI','clock + select');box(560,260,260,130,'Device A','CE0');box(1100,260,320,130,'Device B','CE1');arrow(320,305,560,305);d.line((320,350,460,350,460,430,1000,430,1000,340),fill='#555',width=4);arrow(1000,340,1100,340)
        box(20,480,300,130,'UART','TX / RX');box(760,480,660,130,'Another device','TX to RX and RX to TX');arrow(320,540,760,540)
    im.save(QA/(name+'.png'))
for n in ['architecture','power','led','buses']: diagram(n,n)

