def p(text='',boldlead=False):
    q=doc.add_paragraph()
    if boldlead and ' ' in text:
        a,b=text.split(' ',1);q.add_run(a+' ').bold=True;q.add_run(b)
    else:q.add_run(text)
    return q
def h(text,level=2):doc.add_paragraph(text,'Heading '+str(level))
def page(title):
    q=doc.add_paragraph(title,'Heading 1');q.paragraph_format.page_break_before=True
def pic(path,width=6.3,caption=''):
    q=doc.add_paragraph();q.alignment=WD_ALIGN_PARAGRAPH.CENTER;q.add_run().add_picture(str(path),width=Inches(width))
    if caption:
        q=p(caption);q.paragraph_format.space_after=Pt(8)
        for r in q.runs:r.font.size=Pt(9);r.font.color.rgb=RGBColor(80,80,80)
def table(headers,rows,widths=None,size=10):
    t=doc.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    if widths:
        for c,w in zip(t.columns,widths):c.width=Inches(w)
    for c,txt in zip(t.rows[0].cells,headers):c.text=txt
    pr=t.rows[0]._tr.get_or_add_trPr();rep=OxmlElement('w:tblHeader');pr.append(rep)
    for vals in rows:
        for c,txt in zip(t.add_row().cells,vals):c.text=str(txt)
    for i,row in enumerate(t.rows):
        pr=row._tr.get_or_add_trPr();pr.append(OxmlElement('w:cantSplit'))
        for j,c in enumerate(row.cells):
            if widths:c.width=Inches(widths[j])
            c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            cp=c._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
            for side in ['top','left','bottom','right']:
                e=OxmlElement('w:'+side);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');b.append(e)
            cp.append(b);sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'222222' if i==0 else ('F7F7F7' if i%2==0 else 'FFFFFF'));cp.append(sh)
            margins=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                e=OxmlElement('w:'+side);e.set(qn('w:w'),'50' if len(rows)>15 else '80');e.set(qn('w:type'),'dxa');margins.append(e)
            cp.append(margins)
            for q in c.paragraphs:
                q.paragraph_format.space_after=Pt(0 if len(rows)>15 else 2);q.paragraph_format.space_before=Pt(0 if len(rows)>15 else 2);q.paragraph_format.line_spacing=1.05
                for r in q.runs:r.font.name='Tahoma';r.font.size=Pt(size);r.font.bold=i==0;r.font.color.rgb=RGBColor(255,255,255) if i==0 else RGBColor(0,0,0)
    p()
def code(text):
    q=p(text);q.paragraph_format.space_after=Pt(9)
    for r in q.runs:r.font.name='Consolas';r.font.size=Pt(10)
