def link(paragraph,text,url):
    from docx.opc.constants import RELATIONSHIP_TYPE as RT
    a=OxmlElement('w:hyperlink');a.set(qn('r:id'),paragraph.part.relate_to(url,RT.HYPERLINK,is_external=True));r=OxmlElement('w:r');rp=OxmlElement('w:rPr');color=OxmlElement('w:color');color.set(qn('w:val'),'245786');rp.append(color);r.append(rp);t=OxmlElement('w:t');t.text=text;r.append(t);a.append(r);paragraph._p.append(a)
for num,title,desc,url in refs:
    q=p();link(q,'['+num+'] '+title,url);q.add_run('\n'+desc)
    q.paragraph_format.keep_together=True
    for r in q.runs:r.font.size=Pt(10)

for q in doc.paragraphs:
    for r in q.runs:
        if r.font.name!='Consolas':
            rp=r._r.get_or_add_rPr();rf=rp.find(qn('w:rFonts'))
            if rf is None:rf=OxmlElement('w:rFonts');rp.insert(0,rf)
            rf.set(qn('w:cs'),'Tahoma');rf.set(qn('w:eastAsia'),'Tahoma')
    # Thai language hints let Word apply native dictionary-based line breaking.
    pp=q._p.get_or_add_pPr();lang=OxmlElement('w:lang');lang.set(qn('w:val'),'th-TH')
    for r in q.runs:r._r.get_or_add_rPr().append(deepcopy(lang))
